#include "checkpoint.hpp"
int main(int argc,char**argv){try{require(argc==3,"checkpoint_test base output");Fvecs base(argv[1]);fs::path out=argv[2];fs::create_directories(out);hnswlib::InnerProductSpace space(base.d);HNSW original(&space,base.n,32,200,20260828);size_t cut=base.n/2;for(size_t i=0;i<cut;++i)original.addPoint(base.row(i),i);save_checkpoint(original,base,out/"partial.gz",1.0);auto saved=load_checkpoint(out/"partial.gz",base,&space);auto restored=std::move(saved.first);require(restored->cur_element_count==cut,"partial count");
 auto identical=[&](){require(original.cur_element_count==restored->cur_element_count,"count mismatch");for(size_t i=0;i<original.cur_element_count;++i){require(original.getExternalLabel(i)==restored->getExternalLabel(i)&&original.element_levels_[i]==restored->element_levels_[i],"identity mismatch");require(std::memcmp(original.getDataByInternalId(i),restored->getDataByInternalId(i),base.d*4)==0,"vector mismatch");for(int l=0;l<=original.element_levels_[i];++l){auto a=original.get_linklist_at_level(i,l),b=restored->get_linklist_at_level(i,l);auto n=original.getListCount(a);require(n==restored->getListCount(b)&&std::memcmp(a+1,b+1,n*4)==0,"ordered links mismatch");}}};identical();for(size_t i=cut;i<base.n;++i){original.addPoint(base.row(i),i);restored->addPoint(base.row(i),i);}identical();original.setEf(1500);restored->setEf(1500);for(size_t i=0;i<128;++i)require(hnsw_result(original,base.row(i))==hnsw_result(*restored,base.row(i)),"continued query mismatch");write_json(out/"complete.json",{{"status","PASS"},{"partial_nodes",cut},{"final_nodes",base.n},{"exact_all_node_ordered_neighbor_comparison",true},{"random_state_continuation_verified",true},{"query_bit_parity",128}});return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
